def plan_for(document_hash, cik):
    spec = REVIEWED.get(document_hash)
    if spec is None or spec['cik'] != str(int(cik)).zfill(10):
        return None
    facts = []
    for table, data in spec['tables'].items():
        for row, tag, label, unit, scale, values in data['rows']:
            for (start, end, column), value in zip(data['periods'], values):
                facts.append(dict(concept=spec['namespace'] + tag,
                    period_start=start, period_end=end, unit=unit, scale=scale,
                    decimals='2' if unit == 'USD/shares' else str(-scale),
                    expected_value=value, label=label, evidence=spec['evidence'],
                    table_proof=dict(heading=data['heading'], headers=data['headers']),
                    locator=dict(kind='cells', table=table, row=row, label_column=0,
                        columns=[column, column + 1] if value.startswith('-') else [column])))
    body = dict(version=VERSION, document_hash=document_hash, cik=spec['cik'],
                scope='reviewed_observations', facts=facts)
    return dict(body, plan_hash=digest(body))
